previewCss:
.darma-loader-darma-b12-eye-blink { --accent: var(--loader-color, #8b5cf6); --accent-2: var(--loader-secondary-color, #22d3ee); width: var(--loader-size, 104px); height: calc(var(--loader-size, 104px) * .56); display: grid; place-items: center; }
.darma-loader-darma-b12-eye-blink .darma-loader-darma-b12-eye-blink__eye { position: relative; width: 100%; height: 100%; display: grid; place-items: center; overflow: hidden; border-radius: 50%; background: #f8fafc; box-shadow: inset 0 0 0 3px var(--accent-2), inset 0 -6px 10px rgba(15, 23, 42, .12); }
.darma-loader-darma-b12-eye-blink .darma-loader-darma-b12-eye-blink__eye span { width: 36%; height: 64%; border-radius: 50%; background: radial-gradient(circle at 50% 50%, #0f172a 32%, var(--accent) 34%, var(--accent-2)); animation: darma-loader-darma-b12-eye-blink-gaze calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b12-eye-blink .darma-loader-darma-b12-eye-blink__eye::after { content: ''; position: absolute; z-index: 2; inset: 0; border-radius: 50%; transform-origin: center top; background: var(--accent); animation: darma-loader-darma-b12-eye-blink-blink calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
@keyframes darma-loader-darma-b12-eye-blink-gaze { 0%, 100% { transform: translateX(-38%); } 50% { transform: translateX(38%); } }
@keyframes darma-loader-darma-b12-eye-blink-blink { 0%, 38% { transform: scaleY(0); } 48%, 54% { transform: scaleY(1); } 64%, 100% { transform: scaleY(0); } }

